-					sizeof(struct dot11_frame_header) +
-					sizeof(struct llc_header) +
-					sizeof(struct dot1X_header) +
-					sizeof(struct eap_header)
-	);
+	wfa = (struct wfa_expanded_header *) (packet + offset);
+	offset += sizeof(struct wfa_expanded_header);

